#' Plot X-13 seasonal adjustment, trend in a facet plot
#'
#' Generates a \code{ggplot} object with a time series facet plot that compares 
#' an X-13 seasonal adjustment and trend, extracted from a \code{seas} object. 
#' The plot optionally includes the original series.
#'
#' Version 7.1 2026-10-30
#'
#' @param seas_obj \code{seas} object for a single series generated by the
#'        \code{seasonal} package \insertCite{seasonal2018}{blsplotGG}.
#'        This is a required entry.
#' @param plot_ori Logical scalar, indicates if original series is included with plot. 
#'        Default is \code{TRUE}.
#' @param main_title Character string; title for the plot. 
#'        By default, the routine will generate a title based on the 
#'        type of adjustment (X-11 and SEATS) done.
#' @param sub_title Subtitle for the plot. Optional entry.
#' @param this_x_label Label for X-axis.  Default is \code{"Time"}
#' @param this_y_label Label for Y-axis.  Default is \code{" "}
#' @param do_grid Logical scalar; indicates if certain plots will have grid lines. 
#'        Default is no grid lines. 
#' @param do_background Logical scalar; indicates grey background included in plot.
#'        Default is no grey background;
#' @param line_color Character vector of length 2 (if \code{plot_ori} is \code{FALSE})
#'        or 3 (if \code{plot_ori} is \code{TRUE}); color used for lines in the plot,
#'        in the order of original series (if specified), seasonally adjusted series, trend. 
#'        Default is generated from the \code{RColorBrewer} palette \code{"Dark2"}.
#'        For a listing of R color codes, 
#'        see \insertCite{rchartsColors;textual}{blsplotGG}.
#' @param this_palette Character string; default \code{RColorBrewer} palette \insertCite{RColorBrewer}{blsplotGG}.
#'        Deault is \code{"Dark2"}.
#' @param line_label Caracter vector of length 2; labels used for lines in the plot,
#'        in the order of original series, seasonally adjusted series. 
#'        Default is \code{c("Ori", "SA", "Trend")} (if original series plotted) or
#'        \code{c("SA", "Trend")}.
#' @param facet_scale Character scalar; set the scale for the y-axis of the facet plots. 
#'        Default is \code{"fixed"}.  To set axis to be different for the different plots,
#'        set \code{facet_scale = "free_y"}.
#' @param facet_text_size Numeric scalar; size of text in facet labels. 
#'        Default is set by the \code{ggplot2} package.
#' @return A \code{ggplot} object that generates a facet plot comparing a 
#'         seasonally adjusted series with the trend generated from the same
#'         X-13ARIMA-SEATS seasonal adjustment.
#'
#' @author Brian C. Monsell, \email{monsell.brian@@bls.gov} or \email{bcmonsell@@gmail.com}
#'
#' @references
#'  \insertAllCited{}
#'
#' @examples
#' ukgas_x11_seas   <- 
#'     seasonal::seas(UKgas, series.period = 4, 
#'         arima.model = "(0 1 1)(0 1 1)", 
#'         transform.function = "log", forecast.maxlead = 20,
#'         x11.seasonalma = "s3x5", x11.save = "d12",
#'         check.print = c( 'pacf', 'pacfplot' ))
#' ukgas_x11_sadj_and_trend_facet_p <- 
#'     plot_sadj_and_trend_facet(ukgas_x11_seas, plot_ori = TRUE,
#'         main_title = "UK Gas",
#'         sub_title = "X-11 Seasonal Adjustment",
#'         line_color = c("steelblue", "forestgreen", "grey"))
#' ukgas_seats_seas <- 
#'     seasonal::seas(UKgas, series.period = 4, 
#'         arima.model = "(0 1 1)(0 1 1)", 
#'         transform.function = "log", forecast.maxlead = 20,
#'         seats.save = "s12",
#'         check.print = c( 'pacf', 'pacfplot' ))
#' ukgas_seats_sadj_and_trend_facet_p <- 
#'     plot_sadj_and_trend_facet(ukgas_seats_seas, plot_ori = FALSE, 
#'         main_title = "UK Gas Series",
#'         sub_title = "SEATS Seasonal Adjustment",
#'         line_color = c("steelblue", "forestgreen"))
#' @importFrom magrittr %>%
#' @importFrom rlang .data
#' @importFrom Rdpack reprompt
#' @export
#' @author Brian C. Monsell, \email{monsell.brian@@bls.gov} or \email{bcmonsell@@gmail.com}
plot_sadj_and_trend_facet <- 
	function(seas_obj = NULL, 
		plot_ori = TRUE, 
		main_title = NULL, 
		sub_title = NULL, 
		this_x_label = "Time", 
		this_y_label = " ", 
		do_grid = FALSE,
		do_background = FALSE,
		line_color = NULL,
		this_palette = "Dark2",
		line_label = NULL,
		facet_scale = "fixed",
		facet_text_size = NULL) {
  # Author: Brian C. Monsell (OEUS) Version 7.1 2026-10-30

  # check if a value is specified for \code{seas_obj}
    if (is.null(seas_obj)) {
      cat("must specify a seas object")
      return(NULL)
    } else {
    # check if a seas object is specified for \code{seas_obj}
      if (!inherits(seas_obj, "seas")) {
        cat("First argument must be a seas object")
        return(NULL)
      }
    }

	this_sadj  <- seasonal::final(seas_obj)
	this_trend <- seasonal::trend(seas_obj)
	if (plot_ori) {
		this_ori <- seasonal::original(seas_obj)
		if (length(this_ori) > length(this_sadj)) {
			this_start <- start(this_sadj)
			this_end <- end(this_sadj)
			this_frequency <- frequency(this_sadj)
			this_ori <- 
			  window(this_ori, start = this_start, end = this_end, frequency = this_frequency)
		}
	}
	
	if ("seatsadj" %in% names(seasonal::udg(seas_obj))) {
		this_sa_type <- "SEATS"
	} else {
		this_sa_type <- "X-11"
	}
	
	if (is.null(main_title)) {
		main_title <- 
			paste0(this_sa_type, " Seasonal Adjutment and Trend")
	}
    
    num_color <- 3
    if (!plot_ori) {
		num_color <- 2
		if (is.null(line_label)) { 
			line_label <- c("Trend", "SA")
		}
	} else {
		if (is.null(line_label)) { 
			line_label <- c("Ori", "Trend", "SA")
		}
    }
	
    if (is.null(line_color)) {
        line_color <- RColorBrewer::brewer.pal(3, this_palette)[1:num_color]
    } else {
        if (length(line_color) < num_color) {
	    if (length(line_color) > 1) {
                warning("Number of line colors specified less than series plotted.")
                warning("Will use colorRampPalette to increase number of colors.")
                line_color <- grDevices::colorRampPalette(line_color)(num_color)
            }
        }
    }

    if (!plot_ori) {
        this_facet_df <- 
			data.frame(date = tsbox::ts_df(this_sadj)$time, 
				sadj = as.double(this_sadj), 
				trend = as.double(this_trend)) %>% 
			dplyr::select(.data$date, .data$sadj, .data$trend) %>% 
			tidyr::gather(key = "comp", value = "value", -date)
        
        this_facet_df$comp <- factor(this_facet_df$comp, 
                                    levels = c("trend", "sadj"))
        
        p_sadj_trend_facet <- 
			ggplot2::ggplot(this_facet_df, 
				ggplot2::aes(y = .data$value, x = .data$date, 
					color = .data$comp)) +  
			ggplot2::geom_line() + 
			ggplot2::scale_color_manual(values = c("trend" = line_color[2],
                                                   "sadj" = line_color[1]),
				labels = line_label) +
			ggplot2::facet_grid(factor(comp, 
								levels = c("trend", "sadj"),
								labels = line_label) ~ .,
								scale = facet_scale) + 
			ggplot2::labs(title = main_title,
				          subtitle = sub_title,
						  x = this_x_label,
						  y = this_y_label)
        
    } else {
        this_facet_df <- 
            data.frame(date = tsbox::ts_df(this_sadj)$time, 
	            ori = as.double(this_ori), 
				sadj = as.double(this_sadj), 
				trend = as.double(this_trend)) %>%
	        dplyr::select(.data$date, .data$ori, .data$sadj, .data$trend) %>%
	        tidyr::gather(key = "comp", value = "value", -date)

        this_facet_df$comp <- factor(this_facet_df$comp, 
                                     levels = c("ori", "trend", "sadj"))
    
		p_sadj_trend_facet <- 
			ggplot2::ggplot(this_facet_df, 
			                ggplot2::aes(y = .data$value, x = .data$date, 
	                                     color = .data$comp)) +  
			ggplot2::geom_line() + 
			ggplot2::scale_color_manual(values = c("ori" = line_color[3],
				                                   "trend" = line_color[2],
				                                   "sadj" = line_color[1]),
                                        labels = line_label) +
			ggplot2::facet_grid(factor(comp, 
								levels = c("ori", "trend", "sadj"),
								labels = line_label) ~ .,
								scale = facet_scale) + 
			ggplot2::labs(title = main_title,
                          subtitle = sub_title,
                          x = this_x_label,
                          y = this_y_label)
    }
    

	# remove grey background if \code{do_background = FALSE} 
    if (!do_background) {
		  p_sadj_trend_facet <- p_sadj_trend_facet + ggplot2::theme_bw()
    }

	# remove grid lines if \code{do_grid = FALSE}
	if (!do_grid) {
	    p_sadj_trend_facet <- p_sadj_trend_facet + 
		    ggplot2::theme(panel.grid.major = ggplot2::element_blank(), 
			               panel.grid.minor = ggplot2::element_blank())
	}
       
	if (!is.null(facet_text_size)) {
		p_sadj_trend_facet <- p_sadj_trend_facet + 
			ggplot2::theme(strip.text = ggplot2::element_text(size = facet_text_size),
				legend.position = "none")
	} else {
		p_sadj_trend_facet <- 
			p_sadj_trend_facet + ggplot2::theme(legend.position = "none")
	}
	
	return(p_sadj_trend_facet)
  }
